import { CTRL_ENTER } from '../../shared/csi-enter';
import type { WTermAdapter } from './wterm';

const isMac = typeof navigator !== 'undefined' && /Mac|iPhone|iPad/.test(navigator.platform);
const punctuation: Record<number, string> = { 186: ';:', 187: '=+', 188: ',<', 189: '-_', 190: '.>', 191: '/?', 192: '`~', 219: '[{', 220: '\\|', 221: ']}', 222: `'"` };

// In Meta mode use the layout's base virtual key, not the character generated by Option.
function optionBase(e: KeyboardEvent) {
  if (e.code === 'Space') return ' ';
  if (e.keyCode >= 65 && e.keyCode <= 90) return String.fromCharCode(e.keyCode + (e.shiftKey ? 0 : 32));
  if (e.keyCode >= 48 && e.keyCode <= 57) return (e.shiftKey ? ')!@#$%^&*(' : '0123456789')[e.keyCode - 48];
  if (e.key === 'Dead' && /^Key[A-Z]$/.test(e.code)) return e.shiftKey ? e.code[3] : e.code[3].toLowerCase();
  return punctuation[e.keyCode]?.[Number(e.shiftKey)];
}

export function deskKeyExceptions(adapter: WTermAdapter) {
  let tabTraversalArmed = false;
  let heldSelectionEscape: string | undefined;
  let selecting: Promise<boolean> | undefined;
  let composing = false;
  const delivered = new Set<string>();
  const forwarded = new WeakSet<KeyboardEvent>();
  const pressed = new Map<string, string>();
  const disarm = () => {
    tabTraversalArmed = false;
  };
  const clearSelection = () => {
    selecting = undefined;
    adapter.native?.clearSelection();
  };
  adapter.onOpen((native, signal) => {
    const textarea = adapter.textarea!;
    // Only an actual Kitty key delivery owns later repeats. A browser copy shortcut also cancels the event.
    let press: KeyboardEvent | undefined;
    textarea.addEventListener('keydown', (e) => (press = e), { capture: true, signal });
    const input = adapter.onData(() => {
      if (press?.currentTarget === textarea && press.cancelBubble && adapter.core?.kittyKeyboardFlags()) delivered.add(press.code || press.key);
    });
    signal.addEventListener('abort', () => input.dispose(), { once: true });
    textarea.addEventListener('compositionstart', () => (composing = true), { signal });
    textarea.addEventListener('compositionend', () => (composing = false), { signal });
    for (const phase of ['compositionstart', 'input', 'paste', 'pointerdown']) native.element.addEventListener(phase, disarm, { capture: true, signal });
    textarea.addEventListener(
      'blur',
      () => {
        disarm();
        heldSelectionEscape = undefined;
        composing = false;
        delivered.clear();
        pressed.clear();
      },
      { signal },
    );
    textarea.addEventListener(
      'paste',
      (e) => {
        const text = e.clipboardData?.getData('text/plain');
        if (!text?.includes('\n') || adapter.modes.bracketedPasteMode) return;
        // Without bracket delimiters the receiving shell expects Return for each line.
        e.preventDefault();
        e.stopImmediatePropagation();
        clearSelection();
        adapter.input(text.replace(/\r?\n/g, '\r'));
      },
      { capture: true, signal },
    );
  });
  return (e: KeyboardEvent, agent: boolean): boolean => {
    if (forwarded.has(e)) return false;
    if ((e.type !== 'keydown' && e.type !== 'keyup') || e.target !== adapter.textarea) return false;
    const down = e.type === 'keydown';
    const keyId = e.code || e.key;
    if (!down) delivered.delete(keyId);
    const heldKey = !down || e.repeat ? pressed.get(e.code) : undefined;
    // End the old pairing even when the IME owns this event or its last release was lost.
    if (!down || !e.repeat) pressed.delete(e.code);
    if (heldSelectionEscape === keyId) {
      if (down && e.repeat) return true;
      heldSelectionEscape = undefined;
      if (!down) return true;
    }
    if (composing || e.isComposing || e.keyCode === 229) return false;
    const unmodified = !e.ctrlKey && !e.altKey && !e.metaKey && !e.shiftKey;
    if (down && tabTraversalArmed && e.key !== 'Shift') {
      disarm();
      if (e.key === 'Tab' && !e.altKey && !e.ctrlKey && !e.metaKey && !e.repeat) {
        e.stopPropagation();
        return false;
      }
    }
    let key: string | undefined;
    if (down && e.key.toLowerCase() === 'a' && !e.altKey && ((e.metaKey && !e.ctrlKey && !e.shiftKey) || (e.ctrlKey && e.shiftKey && !e.metaKey && !e.getModifierState('AltGraph'))) && !delivered.has(keyId) && adapter.native) {
      if (!selecting) {
        // Native's shortcut discards this promise; keep it so Escape can cancel before the first row is available.
        const scan = (selecting = adapter.native.selectAll());
        const settled = () => {
          if (selecting === scan) selecting = undefined;
        };
        void scan.then(settled, settled);
      }
      return true;
    }
    if (e.key === 'Escape' && unmodified) {
      if (down && !e.repeat && adapter.native) {
        const root = adapter.native.element;
        const selection = root.ownerDocument.getSelection();
        if (selecting || adapter.native.getSelectionText() !== null || (selection && !selection.isCollapsed && root.contains(selection.anchorNode) && root.contains(selection.focusNode))) {
          clearSelection();
          heldSelectionEscape = keyId;
          tabTraversalArmed = true;
          return true;
        }
      }
      if (!adapter.core?.kittyKeyboardFlags()) {
        if (down) adapter.input('\x1b');
        return true;
      }
      // Keep native Kitty press/repeat/release for code Escape without arming native Tab traversal.
      key = 'Unidentified';
    }
    if (down && e.key === 'Enter' && !e.altKey && !e.metaKey && !adapter.core?.kittyKeyboardFlags()) {
      // Droid queues Ctrl+Enter before negotiation; a plain shell submits Shift+Enter as Return.
      if (agent && e.ctrlKey && !e.shiftKey) {
        adapter.input(CTRL_ENTER);
        return true;
      }
      if (!agent && e.shiftKey && !e.ctrlKey && !adapter.core?.modifyOtherKeys()) {
        adapter.input('\r');
        return true;
      }
    }
    if (isMac && e.ctrlKey && !e.altKey && !e.metaKey && !e.shiftKey) {
      // Non-Latin layouts still have Latin virtual Control shortcuts. C/V can lack a Latin virtual code.
      let ch = e.key.toLowerCase();
      if (/^\p{L}$/u.test(ch) && !/^[a-z]$/.test(ch)) {
        if (/^Key[CV]$/.test(e.code)) ch = e.code[3].toLowerCase();
        else if (e.keyCode >= 65 && e.keyCode <= 90) ch = String.fromCharCode(e.keyCode + 32);
        key = ch;
      }
      if (ch === 'c' && down) clearSelection(); // Command+C, not Control+C, copies on Mac.
      if (ch === 'v') key = 'V'; // wterm #267 reserves lowercase Ctrl+v for browser paste even on Mac.
    }
    if (isMac && e.altKey && !e.metaKey && !e.ctrlKey && !e.getModifierState('AltGraph') && (e.key === 'Dead' || [...e.key].length === 1)) {
      if (adapter.options.macOptionIsMeta === false) {
        if (down) e.stopPropagation(); // Let native layout text or IME input through, not Alt+key.
        return false;
      }
      key = optionBase(e);
    }
    // A release may have different modifiers than its press; keep the identity, not the modifiers.
    key = heldKey ?? key;
    if (down && !e.repeat && e.code && key) pressed.set(e.code, key);
    if (!key || key === e.key) return false;
    const normalized = new KeyboardEvent(e.type, e);
    const code = key === 'Unidentified' && e.key === 'Escape' ? 'Escape' : e.code || e.key;
    Object.defineProperties(normalized, { key: { value: key }, code: { value: code }, getModifierState: { value: e.getModifierState.bind(e) } });
    forwarded.add(normalized);
    adapter.textarea?.dispatchEvent(normalized);
    return true;
  };
}
